package A_basic.model;
public class Recipient { private final String recipientId; private final String name; private final String contact; public Recipient(String recipientId, String name, String contact) { this.recipientId = recipientId; this.name = name; this.contact = contact; } @Override public String toString() { return "Recipient{" + "recipientId='" + recipientId + "'" + ", name='" + name + "'" + ", contact='" + contact + "'" + '}'; } public String getRecipientId() { return recipientId; } public String getName() { return name; } public String getContact() { return contact; } }
